#!/usr/bin/env bash
# Runs the `product` and `dockerfile` steps of .github/workflows/ansible_playbook.yml, as written, against fixtures.
#   <name>@<version>[+arc].json  product output, byte for byte, generated by
#                                dagger-container-builds@0.4.1 builds/ansible.ProductJson
#   dockerfile.<case>            generated Dockerfile for the files present, per builds/ansible.BuildContainer
set -euo pipefail

root=$(cd "$(dirname "$0")/.." && pwd)
workflow=$root/.github/workflows/ansible_playbook.yml
fixtures=$root/test/fixtures/ansible_playbook
product_step=$(yq '.jobs.product.steps[] | select(.id == "product") | .run' "$workflow")
dockerfile_step=$(yq '.jobs.builds.steps[] | select(.id == "dockerfile") | .run' "$workflow")
work=$(mktemp -d)
trap 'rm -rf "$work"' EXIT

pass=0
fail=0

check() {
  if [ "$2" = "$3" ]; then
    pass=$((pass + 1))
    echo "ok   $1"
  else
    fail=$((fail + 1))
    echo "FAIL $1"
    diff <(printf '%s\n' "$2") <(printf '%s\n' "$3") || true
  fi
}

for expected in "$fixtures"/*@*.json; do
  base=$(basename "$expected" .json)
  name=${base%@*}
  rest=${base#*@}
  version=${rest%+arc}
  arc_hosts=''
  [ "$rest" != "$version" ] && arc_hosts=mac-a
  dir=$work/$RANDOM
  mkdir -p "$dir"
  cp "$fixtures/$name.yaml" "$dir/config.yaml"
  : > "$dir/out"
  (cd "$dir" && CONFIG=config.yaml VERSION=$version ARC=auto ARC_LABEL=arc-arm64 ARC_HOSTS=$arc_hosts \
    GITHUB_OUTPUT=$dir/out bash -c "$product_step" > /dev/null)
  check "product $base" "$(cat "$expected")" "$(sed -n 's/^product=//p' "$dir/out")"
done

# run_dockerfile <case> <files...>; files are created as regular files, `dir:` prefix creates a directory
run_dockerfile() {
  local case=$1 dir=$work/$RANDOM f
  shift
  mkdir -p "$dir/src" "$dir/tmp"
  for f in "$@"; do
    if [[ $f == dir:* ]]; then
      mkdir -p "$dir/src/${f#dir:}"
    else
      mkdir -p "$(dirname "$dir/src/$f")"
      touch "$dir/src/$f"
    fi
  done
  (cd "$dir/src" && UPSTREAM=ghcr.io/example/ansible:6.6-alpine_3.24 RUNNER_TEMP=$dir/tmp \
    bash -c "$dockerfile_step" > /dev/null)
  check "dockerfile $case" "$(cat "$fixtures/dockerfile.$case")" "$(cat "$dir/tmp/Dockerfile")"
  check "dockerignore $case" ".git" "$(cat "$dir/tmp/Dockerfile.dockerignore")"
}

run_dockerfile none config.yaml README.md dir:test.yml dir:meta
run_dockerfile all playbook.yml test.yml meta/requirements.yml requirements.yml
run_dockerfile template config.yaml playbook.yml requirements.yml README.md workflow.yaml

echo "$pass passed, $fail failed"
[ "$fail" -eq 0 ]
